import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const USE_VALUES = ['사용', '미사용'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const INT32_MAX = 2147483647;

function textOf(v: unknown, name: string, max: number, required: boolean): string | null {
  if (v === undefined || v === null || (typeof v === 'string' && v.trim() === '')) {
    if (required) {
      throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값은 필수입니다.');
    }
    return null;
  }
  if (typeof v !== 'string' || v.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 형식이 올바르지 않습니다.');
  }
  return v.trim();
}

function intOf(v: unknown, name: string, required: boolean, max: number): string | null {
  if (v === undefined || v === null || v === '') {
    if (required) {
      throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값은 필수입니다.');
    }
    return null;
  }
  let s: string | null = null;
  if (typeof v === 'number' && Number.isInteger(v) && v >= 0) {
    s = String(v);
  } else if (typeof v === 'string' && /^\d+$/.test(v)) {
    s = v;
  }
  if (s === null || Number(s) > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 은(는) 0 이상의 정수여야 합니다.');
  }
  return s;
}

function useYnOf(v: unknown, required: boolean): string | null {
  const s = textOf(v, '사용 여부', 10, required);
  if (s !== null && !USE_VALUES.includes(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  return s;
}

function pageOf(q: Record<string, unknown>): { page: number; size: number } {
  const page = Number(intOf(q['page'], 'page', false, INT32_MAX) ?? '0');
  let size = Number(intOf(q['size'], 'size', false, INT32_MAX) ?? String(DEFAULT_SIZE));
  if (size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', 'size는 1 이상이어야 합니다.');
  }
  if (size > MAX_SIZE) {
    size = MAX_SIZE;
  }
  return { page, size };
}

@Controller('api/v1')
export class FnSfr00901Controller {
  @Get('/fund-subjects')
  async listFundSubjects(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pageOf(q);
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT fund_subject_id AS "fundSubjectId", subject_name AS "subjectName",
                parent_category AS "parentCategory", use_yn AS "useYn"
           FROM fund_subject
          ORDER BY fund_subject_id
          LIMIT :size OFFSET :offset`,
        { size, offset: page * size },
      );
      const totalRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM fund_subject`,
        {},
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/fund-subjects')
  @HttpCode(200)
  async createFundSubject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const subjectName = textOf(data['subjectName'], '자금과목명', 100, true);
    const parentCategory = textOf(data['parentCategory'], '자금과목 상위 구분', 100, false);
    const useYn = useYnOf(data['useYn'], true);
    return transaction(async (db) => {
      const dup = await db.query(
        `SELECT fund_subject_id FROM fund_subject WHERE subject_name = :subjectName`,
        { subjectName },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'FUND_SUBJECT_DUPLICATED', '이미 존재하는 자금과목명입니다.');
      }
      const rows = await db.query(
        `INSERT INTO fund_subject (subject_name, parent_category, use_yn, created_at, updated_at)
         VALUES (:subjectName, :parentCategory, :useYn, now(), now())
         RETURNING fund_subject_id AS "fundSubjectId"`,
        { subjectName, parentCategory, useYn },
      );
      return rows[0];
    });
  }

  @Patch('/fund-subjects/:fundSubjectId')
  async updateFundSubject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = intOf(req.params['fundSubjectId'], '자금과목 ID', true, Number.MAX_SAFE_INTEGER);
    const data = checks.inputOf(req.body);
    const subjectName = textOf(data['subjectName'], '자금과목명', 100, false);
    const parentCategory = textOf(data['parentCategory'], '자금과목 상위 구분', 100, false);
    const useYn = useYnOf(data['useYn'], false);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT fund_subject_id FROM fund_subject WHERE fund_subject_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FUND_SUBJECT_NOT_FOUND', '자금과목을 찾을 수 없습니다.');
      }
      if (subjectName !== null) {
        const dup = await db.query(
          `SELECT fund_subject_id FROM fund_subject
            WHERE subject_name = :subjectName AND fund_subject_id <> CAST(:id AS bigint)`,
          { subjectName, id },
        );
        if (dup.length > 0) {
          throw new ApiError(409, 'FUND_SUBJECT_DUPLICATED', '이미 존재하는 자금과목명입니다.');
        }
      }
      await db.execute(
        `UPDATE fund_subject
            SET subject_name = COALESCE(:subjectName, subject_name),
                parent_category = COALESCE(:parentCategory, parent_category),
                use_yn = COALESCE(:useYn, use_yn),
                updated_at = now()
          WHERE fund_subject_id = CAST(:id AS bigint)`,
        { subjectName, parentCategory, useYn, id },
      );
      return { fundSubjectId: Number(id) };
    });
  }

  @Get('/fund-profit-form-items')
  async listFundProfitFormItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pageOf(q);
    const formName = textOf(q['formName'], '자금 손익 양식명', 100, false);
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT fund_profit_form_item_id AS "fundProfitFormItemId", form_name AS "formName",
                fund_subject_id AS "fundSubjectId", sort_order AS "sortOrder"
           FROM fund_profit_form_item
          WHERE (CAST(:formName AS varchar) IS NULL OR form_name = :formName)
          ORDER BY form_name, sort_order, fund_profit_form_item_id
          LIMIT :size OFFSET :offset`,
        { formName, size, offset: page * size },
      );
      const totalRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM fund_profit_form_item
          WHERE (CAST(:formName AS varchar) IS NULL OR form_name = :formName)`,
        { formName },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/fund-profit-form-items')
  @HttpCode(200)
  async createFundProfitFormItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const formName = textOf(data['formName'], '자금 손익 양식명', 100, true);
    const fundSubjectId = intOf(data['fundSubjectId'], '자금과목', true, Number.MAX_SAFE_INTEGER);
    const sortOrder = intOf(data['sortOrder'], '정렬 순서', false, INT32_MAX);
    return transaction(async (db) => {
      const subject = await db.query(
        `SELECT use_yn AS "useYn" FROM fund_subject WHERE fund_subject_id = CAST(:fundSubjectId AS bigint)`,
        { fundSubjectId },
      );
      if (subject.length === 0) {
        throw new ApiError(404, 'FUND_SUBJECT_NOT_FOUND', '자금과목을 찾을 수 없습니다.');
      }
      if (subject[0]['useYn'] !== '사용') {
        throw new ApiError(422, 'FUND_SUBJECT_NOT_IN_USE', '미사용 자금과목은 구성 항목으로 지정할 수 없습니다.');
      }
      const dup = await db.query(
        `SELECT fund_profit_form_item_id FROM fund_profit_form_item
          WHERE form_name = :formName AND fund_subject_id = CAST(:fundSubjectId AS bigint)`,
        { formName, fundSubjectId },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'INVALID_STATE', '이미 양식에 포함된 자금과목입니다.');
      }
      const rows = await db.query(
        `INSERT INTO fund_profit_form_item (form_name, fund_subject_id, sort_order, created_at, updated_at)
         VALUES (:formName, CAST(:fundSubjectId AS bigint), CAST(:sortOrder AS integer), now(), now())
         RETURNING fund_profit_form_item_id AS "fundProfitFormItemId"`,
        { formName, fundSubjectId, sortOrder },
      );
      return rows[0];
    });
  }

  @Patch('/fund-profit-form-items/:fundProfitFormItemId')
  async updateFundProfitFormItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = intOf(req.params['fundProfitFormItemId'], '양식 구성 ID', true, Number.MAX_SAFE_INTEGER);
    const data = checks.inputOf(req.body);
    const formName = textOf(data['formName'], '자금 손익 양식명', 100, false);
    const fundSubjectId = intOf(data['fundSubjectId'], '자금과목', false, Number.MAX_SAFE_INTEGER);
    const sortOrder = intOf(data['sortOrder'], '정렬 순서', false, INT32_MAX);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT form_name AS "formName", fund_subject_id AS "fundSubjectId"
           FROM fund_profit_form_item
          WHERE fund_profit_form_item_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FUND_PROFIT_FORM_ITEM_NOT_FOUND', '양식 구성 항목을 찾을 수 없습니다.');
      }
      if (fundSubjectId !== null) {
        const subject = await db.query(
          `SELECT use_yn AS "useYn" FROM fund_subject WHERE fund_subject_id = CAST(:fundSubjectId AS bigint)`,
          { fundSubjectId },
        );
        if (subject.length === 0) {
          throw new ApiError(404, 'FUND_SUBJECT_NOT_FOUND', '자금과목을 찾을 수 없습니다.');
        }
        // 가정: 수정으로 자금과목을 바꿀 때도 미사용 과목은 지정할 수 없다.
        if (subject[0]['useYn'] !== '사용') {
          throw new ApiError(422, 'FUND_SUBJECT_NOT_IN_USE', '미사용 자금과목은 구성 항목으로 지정할 수 없습니다.');
        }
      }
      if (formName !== null || fundSubjectId !== null) {
        const nextName = formName ?? String(found[0]['formName']);
        const nextSubject = fundSubjectId ?? String(found[0]['fundSubjectId']);
        const dup = await db.query(
          `SELECT fund_profit_form_item_id FROM fund_profit_form_item
            WHERE form_name = :nextName
              AND fund_subject_id = CAST(:nextSubject AS bigint)
              AND fund_profit_form_item_id <> CAST(:id AS bigint)`,
          { nextName, nextSubject, id },
        );
        if (dup.length > 0) {
          throw new ApiError(409, 'INVALID_STATE', '이미 양식에 포함된 자금과목입니다.');
        }
      }
      await db.execute(
        `UPDATE fund_profit_form_item
            SET form_name = COALESCE(:formName, form_name),
                fund_subject_id = COALESCE(CAST(:fundSubjectId AS bigint), fund_subject_id),
                sort_order = COALESCE(CAST(:sortOrder AS integer), sort_order),
                updated_at = now()
          WHERE fund_profit_form_item_id = CAST(:id AS bigint)`,
        { formName, fundSubjectId, sortOrder, id },
      );
      return { fundProfitFormItemId: Number(id) };
    });
  }
}

