import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  Select,
  LookupSelect,
  RefName,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;
const USE_OPTIONS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];

type DrawerState =
  | { kind: 'subject'; row?: Row }
  | { kind: 'item'; row?: Row }
  | null;

function SubjectForm({ role, row, onDone }: { role: string; row?: Row; onDone: () => void }) {
  const [subjectName, setSubjectName] = useState<unknown>(row?.subjectName ?? '');
  const [parentCategory, setParentCategory] = useState<unknown>(row?.parentCategory ?? '');
  const [useYn, setUseYn] = useState<unknown>(row?.useYn ?? '사용');
  return (
    <Form
      submit={row ? '수정' : '등록'}
      onSubmit={async () => {
        if (!String(subjectName).trim()) {
          throw new Error('자금과목명을 입력하세요.');
        }
        if (!useYn) {
          throw new Error('사용 여부를 선택하세요.');
        }
        const body: Row = {
          subjectName: String(subjectName).trim(),
          parentCategory: String(parentCategory).trim(),
          useYn,
        };
        if (row) {
          await call('PATCH', '/fund-subjects/' + row.fundSubjectId, role, body);
        } else {
          await call('POST', '/fund-subjects', role, body);
        }
        onDone();
      }}
    >
      <Field label="자금과목명" required>
        <TextInput value={subjectName} onChange={setSubjectName} />
      </Field>
      <Field label="자금과목 상위 구분">
        <TextInput value={parentCategory} onChange={setParentCategory} />
      </Field>
      <Field label="사용 여부" required>
        <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} />
      </Field>
    </Form>
  );
}

function ItemForm({ role, row, onDone }: { role: string; row?: Row; onDone: () => void }) {
  const [formName, setFormName] = useState<unknown>(row?.formName ?? '');
  const [fundSubjectId, setFundSubjectId] = useState<unknown>(row?.fundSubjectId ?? '');
  const [sortOrder, setSortOrder] = useState<unknown>(row?.sortOrder ?? '');
  return (
    <Form
      submit={row ? '수정' : '등록'}
      onSubmit={async () => {
        if (!String(formName).trim()) {
          throw new Error('자금 손익 양식명을 입력하세요.');
        }
        if (fundSubjectId === '' || fundSubjectId === null || fundSubjectId === undefined) {
          throw new Error('자금과목을 선택하세요.');
        }
        const body: Row = {
          formName: String(formName).trim(),
          fundSubjectId,
          sortOrder,
        };
        if (row) {
          await call('PATCH', '/fund-profit-form-items/' + row.fundProfitFormItemId, role, body);
        } else {
          await call('POST', '/fund-profit-form-items', role, body);
        }
        onDone();
      }}
    >
      <Field label="자금 손익 양식명" required>
        <TextInput value={formName} onChange={setFormName} />
      </Field>
      <Field label="자금과목" required>
        <LookupSelect table="fund_subject" role={role} value={fundSubjectId} onChange={setFundSubjectId} />
      </Field>
      <Field label="정렬 순서">
        <NumberInput value={sortOrder} onChange={setSortOrder} />
      </Field>
    </Form>
  );
}

export default function FnSfr00901Page({ role, notify }: PageProps) {
  const [subjectPage, setSubjectPage] = useState(0);
  const [itemPage, setItemPage] = useState(0);
  const [formDraft, setFormDraft] = useState<unknown>('');
  const [formName, setFormName] = useState('');
  const [drawer, setDrawer] = useState<DrawerState>(null);

  const subjects = useData<Page>(
    () => call<Page>('GET', '/fund-subjects', role, undefined, { page: subjectPage, size: SIZE }),
    [role, subjectPage],
  );
  const items = useData<Page>(
    () =>
      call<Page>('GET', '/fund-profit-form-items', role, undefined, {
        page: itemPage,
        size: SIZE,
        formName,
      }),
    [role, itemPage, formName],
  );

  const done = (message: string) => {
    setDrawer(null);
    notify(message);
    subjects.reload();
    items.reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>설정 현황</h2>
        <Tiles
          items={[
            ['자금과목', subjects.data?.total ?? 0],
            ['양식 구성 항목', items.data?.total ?? 0],
          ]}
        />
      </section>

      <section className="box span-6">
        <h2>자금과목</h2>
        <Band total={subjects.data?.total}>
          <button type="button" onClick={() => setDrawer({ kind: 'subject' })}>
            자금과목 등록
          </button>
        </Band>
        {subjects.error ? <p>{subjects.error}</p> : null}
        <DataTable
          columns={[
            { key: 'subjectName', label: '자금과목명' },
            { key: 'parentCategory', label: '자금과목 상위 구분' },
            { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r.useYn} /> },
          ]}
          rows={subjects.data?.items ?? []}
          onRowClick={(r) => setDrawer({ kind: 'subject', row: r })}
          empty="등록된 자금과목이 없습니다."
        />
        <Pager
          page={subjectPage}
          size={SIZE}
          total={subjects.data?.total ?? 0}
          onPage={setSubjectPage}
        />
      </section>

      <section className="box span-6">
        <h2>자금 손익 양식</h2>
        <Filters
          onSearch={() => {
            setItemPage(0);
            setFormName(String(formDraft).trim());
          }}
          onReset={() => {
            setFormDraft('');
            setItemPage(0);
            setFormName('');
          }}
        >
          <Field label="자금 손익 양식명">
            <TextInput value={formDraft} onChange={setFormDraft} />
          </Field>
        </Filters>
        <Band total={items.data?.total}>
          <button type="button" onClick={() => setDrawer({ kind: 'item' })}>
            구성 항목 등록
          </button>
        </Band>
        {items.error ? <p>{items.error}</p> : null}
        <DataTable
          columns={[
            { key: 'formName', label: '자금 손익 양식명' },
            {
              key: 'fundSubjectId',
              label: '자금과목',
              render: (r) => <RefName table="fund_subject" role={role} value={r.fundSubjectId} />,
            },
            { key: 'sortOrder', label: '정렬 순서' },
          ]}
          rows={items.data?.items ?? []}
          onRowClick={(r) => setDrawer({ kind: 'item', row: r })}
          empty="등록된 구성 항목이 없습니다."
        />
        <Pager
          page={itemPage}
          size={SIZE}
          total={items.data?.total ?? 0}
          onPage={setItemPage}
        />
      </section>

      {drawer?.kind === 'subject' ? (
        <Drawer title={drawer.row ? '자금과목 수정' : '자금과목 등록'} onClose={() => setDrawer(null)}>
          <SubjectForm
            role={role}
            row={drawer.row}
            onDone={() => done(drawer.row ? '자금과목을 수정했습니다.' : '자금과목을 등록했습니다.')}
          />
        </Drawer>
      ) : null}
      {drawer?.kind === 'item' ? (
        <Drawer title={drawer.row ? '구성 항목 수정' : '구성 항목 등록'} onClose={() => setDrawer(null)}>
          <ItemForm
            role={role}
            row={drawer.row}
            onDone={() => done(drawer.row ? '구성 항목을 수정했습니다.' : '구성 항목을 등록했습니다.')}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
